// @vitest-environment node
import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { resolve } from 'node:path';
import sharp from 'sharp';
import { manifest } from './manifest.js';

/**
 * [P31] The installed app had no recognisable icon: every manifest icon was a flat blue square (a July
 * placeholder), and no page declared a favicon or an apple-touch-icon. The icon is now the brand mark, generated by
 * apps/web/scripts/gen-icons.mjs.
 * [P89 · owner, Prompt 86] The mark is now the Marker logo disc alone (plan/brand.md): a black disc holding a T, a white
 * stem under a level yellow bar (was the terracotta Fraunces T on paper). The favicon and the 192/512 icons are the disc
 * (transparent corners); the maskable and Apple icons are full-bleed ink (the launcher's mask makes the disc).
 */
const pub = (p: string) => resolve(process.cwd(), 'apps/web/public', p.replace(/^\//, ''));
type RGB = { r: number; g: number; b: number };
const INK = { r: 0x0a, g: 0x0a, b: 0x0a };
const YELLOW = { r: 0xff, g: 0xe4, b: 0x5c };
const WHITE = { r: 0xff, g: 0xff, b: 0xff };
const near = (a: RGB, b: RGB) => Math.abs(a.r - b.r) + Math.abs(a.g - b.g) + Math.abs(a.b - b.b) < 24;

async function look(file: string) {
  const img = sharp(readFileSync(pub(file)));
  const meta = await img.metadata();
  const { data, info } = await img.ensureAlpha().raw().toBuffer({ resolveWithObject: true });
  const at = (x: number, y: number) => { const i = (y * info.width + x) * 4; return { r: data[i]!, g: data[i + 1]!, b: data[i + 2]!, a: data[i + 3]! }; };
  const share = (c: RGB) => { let n = 0; for (let i = 0; i < data.length; i += 4) if (data[i + 3]! > 200 && near({ r: data[i]!, g: data[i + 1]!, b: data[i + 2]! }, c)) n += 1; return n / (info.width * info.height); };
  return { meta, info, at, corner: at(1, 1), yellow: share(YELLOW), ink: share(INK), white: share(WHITE) };
}

describe('[P31→P89] app icons are the brand mark, not placeholders', () => {
  const files = [
    ...manifest.icons.map((i) => ({ src: i.src, size: Number(i.sizes.split('x')[0]), bleed: i.purpose === 'maskable' })),
    { src: '/apple-touch-icon.png', size: 180, bleed: true },
    { src: '/favicon-32.png', size: 32, bleed: false },
  ];
  for (const f of files) {
    it(`${f.src} is a ${f.size}px PNG: the black disc with the yellow bar over the white stem`, async () => {
      const { meta, corner, yellow, ink, white, at, info } = await look(f.src);
      expect(meta.format).toBe('png');
      expect([meta.width, meta.height]).toEqual([f.size, f.size]);
      if (f.bleed) expect(near(corner, INK)).toBe(true); // full-bleed ink
      else expect(corner.a).toBeLessThan(20);            // the disc alone: transparent corners
      expect(ink).toBeGreaterThan(0.3);                  // a black disc, not the old paper
      expect(yellow).toBeGreaterThan(0.03);              // the marker bar
      expect(yellow).toBeLessThan(0.3);
      expect(white).toBeGreaterThan(0.015);              // the stem
      // the bar sits ABOVE the stem: yellow at a third of the height, white at two thirds, on the centre line
      const c = Math.floor(info.width / 2);
      expect(near(at(c, Math.floor(info.height * (f.bleed ? 0.37 : 0.34))), YELLOW)).toBe(true);
      expect(near(at(c, Math.floor(info.height * 0.65)), WHITE)).toBe(true);
    });
  }

  it('the maskable icon keeps the T inside the safe zone (central 80% circle)', async () => {
    const img = sharp(readFileSync(pub('/icons/icon-maskable-512.png')));
    const { data, info } = await img.removeAlpha().raw().toBuffer({ resolveWithObject: true });
    const r = info.width * 0.4; const c = info.width / 2;
    let outside = 0;
    for (let y = 0; y < info.height; y++) for (let x = 0; x < info.width; x++) {
      const i = (y * info.width + x) * 3;
      const px = { r: data[i]!, g: data[i + 1]!, b: data[i + 2]! };
      if ((near(px, YELLOW) || near(px, WHITE)) && Math.hypot(x - c, y - c) > r) outside += 1;
    }
    expect(outside).toBe(0);
  });

  it('[P89] favicon.svg is the disc', () => {
    const svg = readFileSync(pub('/favicon.svg'), 'utf8');
    expect(svg).toContain('<circle cx="15" cy="15" r="15" fill="#0A0A0A"/>');
    expect(svg).toContain('fill="#FFE45C"');
  });

  it('every page declares the favicon and the apple-touch-icon (iOS ignores manifest icons)', () => {
    // [P89] + the seven game pages
    const games = ['', '/property', '/insurance', '/wealth', '/b2b', '/luxury', '/recruitment'].map((p) => `apps/web/game${p}/index.html`);
    for (const page of ['apps/web/index.html', 'apps/web/app.html', 'apps/web/privacy/index.html', 'apps/web/terms/index.html', ...games]) {
      const html = readFileSync(resolve(process.cwd(), page), 'utf8');
      expect(html, page).toMatch(/<link rel="icon" type="image\/png" sizes="32x32" href="\/favicon-32\.png" \/>/);
      expect(html, page).toMatch(/<link rel="apple-touch-icon" href="\/apple-touch-icon\.png" \/>/);
    }
  });
});
